import { Flex, Tag, Text } from "@chakra-ui/react";
import { describeCondition } from "./conditionPhrase";
import { ConditionTag, type ConditionMemory } from "./ConditionTag";

export function ConditionHeader({
  condition,
  memory,
}: {
  readonly condition: string;
  readonly memory: ConditionMemory;
}) {
  const phrase = describeCondition(condition);
  if (!phrase) {
    return (
      <Flex gap="1" alignItems="center" flexWrap="wrap">
        <Text textStyle="sm">If</Text>
        <ConditionTag label={condition} condition={condition} memory={memory} />
      </Flex>
    );
  }
  return (
    <Flex gap="1" alignItems="center" flexWrap="wrap">
      <Text textStyle="sm">If</Text>
      <ConditionTag label={phrase.entry} condition={phrase.path} memory={memory} />
      <Text textStyle="sm">{phrase.verb}</Text>
      <Tag.Root variant="surface" size="sm">
        <Tag.Label>{phrase.value}</Tag.Label>
      </Tag.Root>
    </Flex>
  );
}
